type output struct {
	State string `json:"state"`
	Code  string `json:"code,omitempty"`
}

func emit(out output) {
	if err := json.NewEncoder(os.Stdout).Encode(out); err != nil {
		os.Exit(1)
	}
}

func main() {
	var in map[string]json.RawMessage
	if err := json.NewDecoder(os.Stdin).Decode(&in); err != nil {
		emit(output{State: "error", Code: "INPUT_INVALID"})
		os.Exit(2)
	}
	raw, ok := in[inputKey]
	if !ok {
		emit(output{State: "unevaluable", Code: "missing"})
		return
	}
	if string(raw) == "null" {
		emit(output{State: "unevaluable", Code: "null"})
		return
	}
	var text string
	if err := json.Unmarshal(raw, &text); err != nil {
		emit(output{State: "not-satisfied"})
		return
	}
	value, ok := parseDecimal(text)
	if !ok {
		emit(output{State: "not-satisfied"})
		return
	}
	if value.Sign() > 0 {
		emit(output{State: "satisfied"})
		return
	}
	emit(output{State: "not-satisfied"})
}

// parseDecimal accepts only -?digits[.digits]: big.Rat.SetString would also accept
// fractions ("1/2") and exponents ("1e3"), which are not decimal syntax here.
func parseDecimal(text string) (*big.Rat, bool) {
	body := text
	if len(body) > 0 && body[0] == '-' {
		body = body[1:]
	}
	digits, dots := 0, 0
	for i := 0; i < len(body); i++ {
		switch c := body[i]; {
		case c >= '0' && c <= '9':
			digits++
		case c == '.' && dots == 0 && digits > 0 && i+1 < len(body):
			dots++
		default:
			return nil, false
		}
	}
	if digits == 0 {
		return nil, false
	}
	return new(big.Rat).SetString(text)
}
